// DETERMINISTIC STEP: Get the raw text output from the AI node
const rawText = $input.first().json.message.content;
let parsedData;

try {
  // Clean up any markdown code blocks the AI might have added
  const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  parsedData = JSON.parse(cleaned);
} catch(e) {
  throw new Error('AI extractor returned invalid JSON: ' + rawText);
}

// Return the parsed data nested securely under the 'resume_data' key
// This is critical because Node 4 is specifically looking for $json.resume_data
return [{
  json: {
    resume_data: parsedData
  }
}];

