// DETERMINISTIC: Parse and validate AI scorer output
const rawText = $input.first().json.message.content;
let scoreData;
try {
  const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  scoreData = JSON.parse(cleaned);
} catch(e) {
  throw new Error('AI scorer returned invalid JSON: ' + rawText);
}

// Deterministic validation
const score = Number(scoreData.overall_score);
if (isNaN(score) || score < 0 || score > 100) {
  throw new Error('Score out of valid range 0-100: ' + scoreData.overall_score);
}

if (!['strong_fit', 'partial_fit', 'low_fit'].includes(scoreData.fit_category)) {
  // Assign category deterministically based on score
  if (score >= 70) scoreData.fit_category = 'strong_fit';
  else if (score >= 40) scoreData.fit_category = 'partial_fit';
  else scoreData.fit_category = 'low_fit';
}

const resumeData = $('3b · Parse Extractor JSON').first().json.resume_data;
const formData = $('1 · Form Trigger').first().json;

return [{
  json: {
    score_data: scoreData,
    overall_score: score,
    fit_category: scoreData.fit_category,
    candidate_name: formData['Candidate Name'],
    candidate_email: formData['Candidate Email'],
    job_description: formData['Job Description'],
    resume_data: resumeData
  }
}];

